// ============================================================ tu casa (Atenas): casa con patio y andrón, donde se puede contratar a un sofista
// Planta de casa ática del siglo IV (como las excavadas al pie del Areópago o en Olinto): patio, pórtico (pastás), andrón con divanes
// y la puerta descentrada, un almacén y el altar de Zeus Herkeios. Jantias, el administrador, contrata al sofista; el sofista elegido
// aparece en el andrón con cinco alumnos y da sus clases con el mismo sistema que las escuelas (n.classes).
const HOUSE={kids:[],sophists:['prodico','hipias','alcidamante','eutidemo']};
function buildMyHouse(){
  const W=16,D=15,h=4;
  // distancia de un punto al borde de la calle más cercana
  const road=(x0,z0)=>{let best=null,bd=1e9;for(const r of ROADS)for(let i=0;i<r.pts.length-1;i++){const p=r.pts[i],q=r.pts[i+1],vx=q[0]-p[0],vz=q[1]-p[1],l=vx*vx+vz*vz||1,t=clamp(((x0-p[0])*vx+(z0-p[1])*vz)/l,0,1),x=p[0]+vx*t,z=p[1]+vz*t,dd=Math.hypot(x-x0,z-z0)-r.w/2;if(dd<bd){bd=dd;best=[x,z,r.w/2];}}return{bd,best};};
  // la fachada mira a la calle más cercana, a tres pasos de ella, y ninguna otra calle cruza el solar
  let c,a,gap=3;
  for(const cand of[[-52,160],[-45,175],[-40,140],[-60,190],[-35,200],[-70,120],[-30,120]]){const c0=AL(cand[0],cand[1]),R=road(c0[0],c0[1]),b=R.best;
    const L=Math.hypot(b[0]-c0[0],b[1]-c0[1])||1,nx=(b[0]-c0[0])/L,nz=(b[1]-c0[1])/L,cc=[b[0]-nx*(D/2+b[2]+gap),b[1]-nz*(D/2+b[2]+gap)],aa=Math.atan2(nx,nz);
    let ok=true;for(let i=-1;i<=1;i+=0.25)for(let j=-1;j<=1;j+=0.25){const p=toW(i*(W/2+1),j*(D/2+1),cc[0],cc[1],aa);if(road(p[0],p[1]).bd<0.5)ok=false;}
    if(ok||!c){c=cc;a=aa;}if(ok)break;}
  // suelo a la altura del punto más alto del solar (el terreno no debe asomar dentro)
  let top=-1e9;for(let i=-1;i<=1;i+=0.25)for(let j=-1;j<=1;j+=0.25){const p=toW(i*W/2,j*D/2,c[0],c[1],a);top=Math.max(top,terrainH(p[0],p[1]));}
  const gy=top-0.08,g=grp(c[0],gy,c[1],a),wm=typeof triplanar==='function'?triplanar(new THREE.MeshLambertMaterial({color:'#efe3c9'}),PTEX.plaster,5):lam('#e8dcc4'),T=0.45,P=(lx,lz)=>toW(lx,lz,c[0],c[1],a);
  Object.assign(HOUSE,{x:c[0],z:c[1],a,gy,g,P});
  const wall=(x1,z1,x2,z2,hh)=>{const L=Math.hypot(x2-x1,z2-z1),m=box(L+(x1===x2||z1===z2?T:0),(hh||h)+1.5,T,wm,(x1+x2)/2,(hh||h)/2-0.75,(z1+z2)/2,g);m.rotation.y=-Math.atan2(z2-z1,x2-x1);
    const p=P(x1,z1),q=P(x2,z2);addSeg(p[0],p[1],q[0],q[1],T/2);};
  // muros exteriores (zócalo de piedra y adobe enlucido) con la puerta de la calle descentrada
  for(const sz of[-1,1]){box(W+0.12,1.6,T+0.12,M.limestone,0,-0.15,sz*(D/2-T/2),g);box(T+0.12,1.6,D+0.12,M.limestone,sz*(W/2-T/2),-0.15,0,g);}
  wall(-W/2,-D/2,W/2,-D/2);wall(-W/2,-D/2,-W/2,D/2);wall(W/2,-D/2,W/2,D/2);wall(-W/2,D/2,-4.9,D/2);wall(-3.1,D/2,W/2,D/2);
  box(1.8,h-2.5,T,wm,-4,2.5+(h-2.5)/2,D/2,g);box(2.2,0.2,T+0.25,M.wood,-4,2.5,D/2,g);
  // andrón (al fondo a la izquierda): puerta descentrada para que quepan los divanes
  wall(-1,-D/2,-1,-2.5);wall(-W/2,-2.5,-2.7,-2.5);wall(-1.3,-2.5,-1,-2.5);box(1.4,h-2.3,T,wm,-2,2.3+(h-2.3)/2,-2.5,g);
  // almacén y cocina (delante a la derecha)
  wall(2,3,2,D/2);wall(2,3,4.4,3);wall(5.8,3,W/2,3);box(1.4,h-2.3,T,wm,5.1,2.3+(h-2.3)/2,3,g);
  // suelos: tierra apisonada en el patio, mosaico de guijarros en el andrón (con el borde elevado donde van los divanes)
  box(W-0.6,0.12,D-0.6,new THREE.MeshLambertMaterial({color:'#bfa985'}),0,0.06,0,g);addPlat(c[0],c[1],W-0.6,D-0.6,a,gy+0.12);
  box(6.4,0.02,4.4,lam('#d9cfb8'),-4.5,0.13,-5,g);box(3.2,0.025,1.6,lam('#3c3a36'),-4.5,0.135,-4.9,g);box(2.8,0.03,1.2,lam('#d9cfb8'),-4.5,0.14,-4.9,g);
  for(let i=0;i<6;i++){const s=box(0.28,0.032,0.28,lam(i%2?'#8a3f2f':'#3c3a36'),-5.7+i*0.48,0.145,-4.9,g);s.rotation.y=Math.PI/4;}
  // zócalo rojo pintado dentro del andrón, como en las casas ricas
  box(6.5,1.1,0.04,lam('#8a3f2f'),-4.5,0.67,-7.25,g);box(0.04,1.1,4.5,lam('#8a3f2f'),-7.75,0.67,-5,g);box(0.04,1.1,4.5,lam('#8a3f2f'),-1.25,0.67,-5,g);
  // pórtico (pastás) del fondo, abierto al patio
  for(const x of[1.6,4.3,7]){const p=P(x,-2.7);addColumn(p[0],gy+0.12,p[1],0.2,h-0.1,a,'doric');}
  // techos y tejados: crujía del fondo y almacén; el patio queda al aire
  const sub=(x,z)=>{const s=new THREE.Group();s.position.set(x,0,z);g.add(s);return s;};
  {const s=sub(0,-5);box(W,0.16,5.4,lam('#7a5a3e'),0,h+0.08,0,s);gableRoof(s,W+0.8,6,h+0.16,1.2,M.tile,wm,true);}
  {const s=sub(5,5.25);box(6,0.16,4.8,lam('#7a5a3e'),0,h+0.08,0,s);gableRoof(s,6.8,5.4,h+0.16,1.1,M.tile,wm,true);}
  // patio: altar de Zeus Herkeios, pozo, telar y unas tinajas
  box(0.9,0.75,0.7,M.limestone,0.5,0.5,0.4,g);box(1.05,0.12,0.85,M.limestone,0.5,0.93,0.4,g);{const p=P(0.5,0.4);addBox(p[0],p[1],1.0,0.8,a);}
  const well=new THREE.Mesh(new THREE.CylinderGeometry(0.55,0.6,0.8,14),M.limestone);well.position.set(-5.6,0.5,1.8);g.add(well);{const p=P(-5.6,1.8);addCirc(p[0],p[1],0.6);}
  box(1.6,1.9,0.12,M.wood,-6.9,1.05,4.8,g).rotation.y=Math.PI/2;for(let i=0;i<9;i++)box(0.06,0.09,0.06,lam('#8a7a62'),-6.85,0.3,4.2+i*0.15,g);
  for(let i=0;i<4;i++){const am=new THREE.Mesh(new THREE.CylinderGeometry(0.22,0.12,0.8,10),lam('#b5734a'));am.position.set(7.4,0.52,4+i*0.7);g.add(am);}
  // andrón: cinco divanes (klinai) con mesitas; los alumnos se sientan en ellos cuando hay clase
  const kline=(lx,lz,ry)=>{const k=new THREE.Group();k.position.set(lx,0.12,lz);k.rotation.y=ry;g.add(k);box(1.9,0.1,0.8,M.wood,0,0.42,0,k);for(const sx of[-0.85,0.85])for(const sz of[-0.33,0.33])box(0.08,0.42,0.08,M.wood,sx,0.21,sz,k);
    box(1.85,0.12,0.74,lam('#b58a4a'),0,0.53,0,k);box(0.4,0.16,0.62,lam('#8a3f2f'),-0.72,0.66,0,k);box(0.7,0.04,0.45,M.wood,0,0.34,0.62,k);const p=P(lx,lz);addCirc(p[0],p[1],0.7);return k;};
  const K=[[-6.4,-6.75,0],[-4.1,-6.75,0],[-7.25,-4.4,Math.PI/2],[-1.75,-5.6,-Math.PI/2],[-7.25,-3.4,Math.PI/2]];
  K.slice(0,4).forEach(k=>kline(...k));
  const lamp=new THREE.Mesh(new THREE.CylinderGeometry(0.05,0.14,1.4,8),M.bronze);lamp.position.set(-2.4,0.82,-6.9);g.add(lamp);
  const lyre=new THREE.Mesh(new THREE.TorusGeometry(0.22,0.03,5,10,Math.PI),M.wood);lyre.position.set(-3,2.3,-7.2);g.add(lyre);
  const sh=new THREE.Mesh(new THREE.CylinderGeometry(0.45,0.45,0.06,18),M.bronze);sh.rotation.x=Math.PI/2;sh.position.set(-6,2.2,-7.2);g.add(sh);
  // alumnos (muchachos de buena familia y un par de mayores que escuchan): visibles solo mientras hay un sofista en casa
  const looks=[['#efe6d2','#4f6a7d'],['#e2d6c0','#8a3f2f'],['#efe6d2','#5c6b3f'],['#e8dfcc','#a07a3a'],['#d7c9ab','#6b4a7a']];
  [[-6.4,-6.6,0],[-4.1,-6.6,0],[-7.1,-4.4,Math.PI/2],[-1.9,-5.6,-Math.PI/2]].forEach(([lx,lz,ry],i)=>{const L=looks[i];
    const k=makePerson({chiton:L[0],himation:L[1],hair:pick(['#2b1f17','#5b4532','#3e2c1f']),beard:i===3,scale:0.9});k.position.set(lx,-0.12,lz);k.rotation.y=ry;g.add(k);
    if(k.userData.arms){k.userData.arms[0].rotation.x=-0.7;k.userData.arms[1].rotation.x=-0.3;}k.visible=false;HOUSE.kids.push(k);});
  {const k=makePerson({chiton:'#a89070',himation:'#7b6a5a',beard:true,hair:'#8d8a85',staff:true});k.position.set(-3.6,0.12,-1.5);k.rotation.y=Math.PI*0.8;g.add(k);k.visible=false;HOUSE.kids.push(k);}
  // herma junto a la puerta, como en casi todas las casas atenienses
  {const p=P(-5.6,D/2+0.8);const hm=box(0.32,1.25,0.32,M.marble,p[0],floorAt(p[0],p[1])+0.62,p[1]);hm.rotation.y=a;const hd=new THREE.Mesh(new THREE.SphereGeometry(0.19,10,8),M.marble);hd.position.set(p[0],floorAt(p[0],p[1])+1.42,p[1]);scene.add(hd);addCirc(p[0],p[1],0.3);}
  footprints.push({x:c[0],z:c[1],w:W,d:D,a,c:'#c9a26a',name:'Tu casa',noFlat:true});
  {const m=toW(-4,D/2+gap/2,c[0],c[1],a);footprints.push({x:m[0],z:m[1],w:5,d:gap+1,a,reserve:true});}
  const st=P(-2.2,D/2+1.6);place('casa','Tu casa','ΟΙΚΙΑ','Una casa ática del siglo IV: muros de adobe enlucido sobre un zócalo de piedra, habitaciones alrededor de un patio con el altar de Zeus Herkeios y un pozo, un pórtico al fondo y el andrón, la sala donde el señor recibe a sus invitados tumbado en divanes. Calias, tu anfitrión ateniense, te la presta mientras estés en la ciudad. Dentro te espera Jantias, el esclavo que la administra: pídele que contrate a un sofista y verás cómo era una clase en casa.',st[0],st[1],a);
  const j=P(2.2,1.2);NPC_POS.mayordomo=[j[0],j[1],a];
  const sp=P(-4.4,-4.3);HOUSE.sophists.forEach(id=>NPC_POS[id]=[sp[0],sp[1],a+Math.PI]);
}
// muestra al sofista contratado (y a los alumnos) y esconde a los demás
function houseApply(){const cur=state.sophist||null;
  for(const o of npcObjs)if(HOUSE.sophists.includes(o.data.id)){const v=o.data.id===cur;o.hidden=!v;o.g.visible=v;}
  HOUSE.kids.forEach(k=>k.visible=!!cur);}
function sophistMenu(n){
  const o=$('dOpts');o.innerHTML='';let k=1;const add=(txt,fn,cls)=>{const b=document.createElement('button');if(cls)b.className=cls;b.innerHTML='<span class="n">'+(k++)+'</span><span>'+txt+'</span>';b.onclick=fn;o.appendChild(b);};
  $('dBody').innerHTML='<p><span class="label">Contratar a un sofista</span></p><p>Puedo mandar recado a cualquiera de estos maestros que están en la ciudad. Vendrá con unos cuantos alumnos de buena familia, que no se pierden una lección así, y os esperará en el andrón. Lo que cobran, amo, mejor no lo pienses: Calias corre con los gastos.</p>';
  HOUSE.sophists.forEach(id=>{const s=NPCS.find(x=>x.id===id);add(s.name+' · '+s.hireLine+(state.sophist===id?' (ya está en casa)':''),()=>{state.sophist=id;save();houseApply();closeDialog();sfxCoin();
    toast('<span class="label">'+s.name+' ha llegado</span><br>Te espera en el andrón, al fondo del patio, con los alumnos.');},state.sophist===id?'seen':'quiz');});
  if(state.sophist)add('Despedir al sofista (los alumnos se marchan)',()=>{state.sophist=null;save();houseApply();$('dBody').innerHTML='<p>Como mandes. Ya se van; el andrón vuelve a estar tranquilo.</p>';renderOpts();});
  add('Volver a la conversación',()=>{$('dBody').innerHTML='<p>¿Algo más, amo?</p>';renderOpts();});
  setTimeout(()=>{const b=o.querySelector('button');b&&b.focus({preventScroll:true});},30);}

const HOUSE_NPCS=[
{id:'mayordomo',name:'Jantias',title:'Esclavo administrador de tu casa',glyph:'Ξ',look:{chiton:'#b8a27a',himation:'#7b6a5a',beard:true,hair:'#5b4532',noHimation:true},
 cat:'Sociedad',lesson:'La casa ateniense',where:'En el patio de tu casa',sophistHire:true,
 summary:'La casa ateniense (oikía) se organizaba alrededor de un patio abierto, con el altar de Zeus Herkeios y a menudo un pozo o una cisterna. Los muros eran de adobe sobre un zócalo de piedra, con pocas ventanas a la calle. El andrón, con la puerta descentrada y el borde del suelo preparado para los divanes, era la sala donde el señor recibía a sus invitados; las mujeres tenían sus habitaciones (gineceo), a veces en el piso alto. El oikos era también la familia y sus bienes, esclavos incluidos. Los sofistas daban a menudo sus lecciones en casas de ricos, como la de Calias que describe Platón en el Protágoras.',
 intro:'¡Bienvenido a casa, amo! Soy Jantias. Calias, tu anfitrión, me manda que te sirva mientras estés en Atenas: barro, compro en el mercado, atiendo la puerta y llevo las cuentas. Si quieres que traiga a un sofista para que dé clase aquí, en el andrón, no tienes más que decirlo.',
 topics:[
  ['¿Esta casa es mía?','Mientras estés en Atenas, sí. Pero de verdad es de Calias. Un forastero no puede ser dueño de casas ni tierras en el Ática, salvo que la Asamblea le conceda ese privilegio, que llaman énktesis; hasta los metecos más ricos viven de alquiler. Por eso Calias te la presta. Él es muy aficionado a los sabios: hace años, en su otra casa, se reunieron a la vez Protágoras, Hipias y Pródico, y medio Atenas fue a escucharlos.'],
  ['¿Cómo es una casa ateniense?','Como esta: de fuera, un muro casi ciego, con una puerta y alguna ventana alta, para que no se vea a las mujeres ni se cuelen los ladrones. De dentro, todo da al patio: el pórtico del fondo, donde se trabaja a la sombra; el andrón, para los banquetes; el almacén y la cocina; y arriba, por una escalera de madera, los dormitorios y el cuarto de las mujeres. Los muros son de adobe: un ladrón puede abrir un agujero con un pico. Por eso a los ladrones los llamamos «horadaparedes».'],
  ['¿Cómo era una clase de sofistas en una casa?','Te cuento lo que vi en casa de Calias, cuando yo era muchacho. En el pórtico paseaba Protágoras, hablando, y detrás le seguía un coro de oyentes, extranjeros que había traído de cada ciudad; cuando él se daba la vuelta, todos se abrían a los lados y volvían a ponerse detrás, como en una danza. Enfrente, Hipias, sentado en un sillón alto, respondía a preguntas sobre los astros. Y en un cuartito que Calias usaba de almacén, Pródico, tumbado y envuelto en mantas, hablaba con una voz tan grave que retumbaba y no se entendía nada. Platón lo ha escrito igual, casi palabra por palabra.']],
 quiz:{q:'¿Qué era el andrón de una casa griega?',a:['La sala donde el señor recibía a sus invitados y celebraba banquetes','El cuarto de las mujeres','El almacén del grano'],ko:'No. El andrón era la sala de los hombres: allí el señor recibía a sus invitados, tumbados en divanes, para los banquetes. Las mujeres tenían su propio espacio, el gineceo.'}},
{id:'prodico',name:'Pródico de Ceos',title:'Sofista, maestro de la exactitud de las palabras',glyph:'Π',look:{chiton:'#efe6d2',himation:'#6a4a3a',beard:true,hair:'#8d8a85',beardC:'#9a968e'},
 cat:'Filosofía',lesson:'Pródico y la exactitud de las palabras',where:'En el andrón de tu casa, si Jantias lo contrata',sophist:true,hireLine:'distinguir palabras y la fábula de Heracles',
 summary:'Pródico de Ceos (c. 465-después del 399) fue sofista y embajador de su isla en Atenas. Se hizo famoso por la «corrección de los nombres»: distinguir con precisión palabras que parecen sinónimas, como discutir y pelear, o alegrarse y disfrutar. Cobraba una dracma por una conferencia breve y cincuenta por la completa. Su fábula de Heracles en la encrucijada, entre el Vicio y la Virtud, la conocemos por Jenofonte (Memorables II 1). Sócrates le tenía aprecio y le enviaba alumnos.',
 intro:'Salud, joven anfitrión, y gracias por el vino tibio; tengo la garganta delicada, ¿sabes? Soy Pródico, de Ceos. Estos muchachos vienen a oírme hablar de la exactitud de las palabras. No es lo mismo escuchar que oír, ni hablar que decir: ya lo verás.',
 topics:[
  ['¿Cuánto cobras?','Depende. Por una dracma doy una muestra: media hora de lo que sé. Por cincuenta dracmas, el curso completo sobre la corrección de los nombres, que deja a cualquiera hablando como es debido. Sócrates dice, riéndose, que él solo pudo pagar la de una dracma, y que por eso no sabe la verdad sobre los nombres. Lo dice para fastidiarme, pero me manda alumnos.'],
  ['¿Para qué sirve distinguir palabras?','Para pensar con claridad. Si en la Asamblea uno dice «valor» y otro entiende «temeridad», discuten sin saber de qué. Si un juez confunde «querer» con «desear», condena mal. Las palabras son como las monedas: si no sabes cuál es de plata y cuál de cobre, te engañan. Antes de discutir, hay que ponerse de acuerdo en los nombres.'],
  ['¿Qué piensas de los dioses?','Pienso, y lo digo en voz baja, que los primeros hombres llamaron dioses a las cosas que les eran útiles: al sol, a los ríos, a las fuentes. Al pan lo llamaron Deméter; al vino, Dioniso; al fuego, Hefesto. Y luego honraron como dioses a quienes descubrieron el cultivo y los oficios. Hay quien dice que eso es impiedad. Yo digo que es gratitud.']],
 quiz:{q:'¿Por qué era famoso Pródico de Ceos?',a:['Por distinguir con exactitud palabras que parecen sinónimas','Por inventar el alfabeto','Por ganar en Olimpia'],ko:'No. Pródico era famoso por la «corrección de los nombres»: distinguir con precisión palabras parecidas, como discutir y pelear.'},
 classIntro:'Pródico se recuesta en el diván, se arregla la manta y carraspea. Los muchachos se callan. «¿Por dónde empezamos?»',
 classWin:'Pródico asiente despacio: «Bien. Has distinguido cada cosa con su nombre. Eso vale más de una dracma».',
 classes:[
  {id:'s_prodico1',title:'Palabras que parecen iguales',pages:['Así se da una clase con un sofista en casa: el maestro, invitado por el dueño, se acomoda en el andrón; los alumnos, muchachos de familias ricas de catorce a dieciocho años, se sientan en los divanes; sus pedagogos esperan junto a la puerta. No hay tablillas: se escucha, se pregunta, se responde y se memoriza. Pródico empieza siempre igual: «Antes de nada, aprended a distinguir los nombres».','«Mirad: discutir no es lo mismo que pelear. Los amigos discuten, con buena voluntad; los enemigos pelean. Alegrarse no es lo mismo que disfrutar: uno se alegra al aprender algo, con la mente; disfruta al comer o beber, con el cuerpo. Estimar no es lo mismo que alabar: estimamos de corazón; alabamos con palabras, a veces sin sentirlo.»','Un muchacho, Critobulo, levanta la mano: «Maestro, ¿y querer y desear?». Pródico sonríe: «Desear es echar de menos lo que no tienes; querer es elegir. El deseo doble es el amor, el eros; el amor doble es la locura». Los alumnos se ríen, y anotan mentalmente. Platón se burlará de estas distinciones; pero son el comienzo del estudio de los sinónimos.'],
   ex:[{q:'Según Pródico, ¿qué diferencia hay entre discutir y pelear?',a:['Los amigos discuten con buena voluntad; los enemigos pelean','No hay ninguna diferencia','Discutir es de esclavos y pelear de ciudadanos'],why:'Pródico distinguía entre discutir (amphisbeteîn), propio de amigos, y pelear (erízein), propio de enemigos.'},
    {q:'¿Qué es «alegrarse» para Pródico, frente a «disfrutar»?',a:['Un gozo de la mente, como al aprender','Un placer del cuerpo, como al comer','Lo mismo que disfrutar'],why:'Alegrarse (euphraínesthai) es de la mente; disfrutar (hédesthai), del cuerpo.'},
    {q:'¿Dónde solía dar sus lecciones un sofista?',a:['En casas de ricos, gimnasios y lugares públicos, cobrando a los alumnos','En escuelas públicas pagadas por la ciudad','Solo en los templos'],why:'No había escuelas públicas de sofistas: daban conferencias y cursos de pago en casas particulares, como la de Calias, y en gimnasios.'}]},
  {id:'s_prodico2',title:'Heracles en la encrucijada',pages:['Pródico recita su obra más famosa, que lleva por todas las ciudades: «Cuando Heracles pasaba de niño a joven, la edad en que se decide qué camino seguir en la vida, se sentó a pensar en un lugar solitario. Y se le acercaron dos mujeres altas».','«Una era hermosa, pintada, mirando a todas partes: era el Vicio, aunque decía llamarse Felicidad. Le prometió el camino más corto y agradable: comer, beber, dormir, amar sin esfuerzo, aprovecharse del trabajo de otros. La otra, sencilla, con la mirada baja y vestida de blanco, era la Virtud: "No te engañaré: nada bueno conceden los dioses sin esfuerzo. Si quieres que la tierra dé fruto, cultívala; si quieres amigos, sírvelos; si quieres que la ciudad te honre, ayúdala".»','Heracles eligió el camino difícil de la Virtud. Pródico pregunta a los alumnos qué habrían elegido, y cada uno debe justificarlo con un breve discurso. Así se enseñaba: con un modelo bien construido (una epídeixis o exhibición), que luego los alumnos imitaban y discutían. Jenofonte pone esta historia en boca de Sócrates; durante siglos se repetirá en escuelas y en pinturas.'],
   ex:[{q:'¿Entre qué dos figuras debe elegir Heracles en la fábula de Pródico?',a:['El Vicio y la Virtud','Atenea y Afrodita','La Guerra y la Paz'],why:'Dos mujeres: el Vicio, que se hace llamar Felicidad, y la Virtud.'},
    {q:'¿Qué le promete la Virtud a Heracles?',a:['Que lo bueno solo se consigue con esfuerzo','Placeres sin trabajo','La inmortalidad inmediata'],why:'La Virtud no engaña: los dioses no dan nada bueno sin esfuerzo.'},
    {q:'¿Qué era una epídeixis?',a:['Un discurso de exhibición que el sofista ofrecía como modelo','Un examen escrito','Una carrera del pentatlón'],why:'La epídeixis era una exhibición pública de oratoria, a menudo para atraer alumnos.'}]}]},
{id:'hipias',name:'Hipias de Elis',title:'Sofista que dice saberlo todo',glyph:'Ι',look:{chiton:'#efe6d2',himation:'#6b2a5a',beard:true,hair:'#5b4532'},
 cat:'Filosofía',lesson:'Hipias: el saber enciclopédico',where:'En el andrón de tu casa, si Jantias lo contrata',sophist:true,hireLine:'el arte de la memoria y el saber de todo',
 summary:'Hipias de Elis (c. 460-después del 399), sofista y embajador de su ciudad, presumía de dominar todas las artes: astronomía, geometría, aritmética, música, gramática, genealogías de héroes y fundaciones de ciudades. Tenía una memoria prodigiosa y enseñaba técnicas para recordar. Contaban que en Olimpia se presentó con todo lo que llevaba hecho por él mismo. Recopiló la lista de vencedores olímpicos. Platón se burla de él en el Hipias mayor y el Hipias menor, y en el Protágoras le atribuye la oposición entre la ley, «tirana de los hombres», y la naturaleza.',
 intro:'¡Por Zeus Olímpico, qué casa tan agradable! Hipias, de Elis. ¿Ves este anillo? Lo hice yo. Y el sello, y las sandalias, y este manto, y el cinturón, que es como los de Persia pero mejor. Pregúntame lo que quieras: astros, números, ritmos, héroes, fundaciones de ciudades. No hay pregunta que no sepa responder.',
 topics:[
  ['¿De verdad lo sabes todo?','Casi. En Olimpia me presenté ante todos los griegos con todo lo que llevaba encima hecho con mis manos, y además con poemas épicos, tragedias, ditirambos y discursos en prosa de mi cosecha. Respondí a cualquier pregunta que me hicieron durante días, y nadie me ganó nunca en nada. ¿Te parece poco?'],
  ['¿Cuánto has ganado?','Más que dos sofistas cualesquiera juntos. En Sicilia, aunque Protágoras había estado antes, gané más de ciento cincuenta minas en poco tiempo, y solo en un pueblecito, Ínico, más de veinte. Los espartanos no me pagan, eso sí: no les dejan sus leyes. Pero les encanta escucharme contar genealogías de héroes y fundaciones de ciudades, como a los niños los cuentos de las abuelas.'],
  ['¿Qué es más fuerte, la ley o la naturaleza?','Os diré lo que dije en casa de Calias: todos los que estáis aquí sois parientes y conciudadanos por naturaleza, no por ley. Lo semejante es pariente de lo semejante. Pero la ley, que es tirana de los hombres, obliga a muchas cosas contra la naturaleza. Cada ciudad tiene leyes distintas y las cambia cuando quiere. La naturaleza es la misma en Elis y en Persia.']],
 quiz:{q:'¿De qué presumía Hipias de Elis?',a:['De saber de todas las artes y de hacerse él mismo su ropa y su anillo','De no saber nada','De no cobrar a sus alumnos'],ko:'No. Hipias presumía de saberlo todo y de llevar puesto solo lo que él mismo había hecho, anillo incluido.'},
 classIntro:'Hipias se sienta en el sillón más alto, como en casa de Calias. «Preguntad, muchachos. O mejor: escuchad y luego os pregunto yo.»',
 classWin:'Hipias aplaude: «¡Excelente! Casi tan bien como yo a tu edad. Bueno, no tanto».',
 classes:[
  {id:'s_hipias1',title:'El arte de la memoria',pages:['Hipias propone un desafío a los alumnos: «Decidme cincuenta nombres, los que queráis». Los muchachos los dicen, desordenados. Hipias los repite todos, en el mismo orden, sin equivocarse. Los alumnos se quedan con la boca abierta. Eso dicen que hacía de verdad, ya de viejo.','«El secreto no es mío del todo», explica. «Lo inventó Simónides, el poeta. Estaba en un banquete y salió un momento; el techo se hundió y los cadáveres quedaron irreconocibles. Él los identificó a todos recordando dónde estaba sentado cada uno. Así descubrió que la memoria funciona con lugares.»','«Imaginad una casa que conozcáis bien, esta misma: la puerta, el patio, el altar, el pozo, el andrón. Poned en cada lugar una imagen llamativa de lo que queréis recordar: en la puerta, un león para el primer argumento; junto al pozo, una espada para el segundo. Luego recorred la casa con la mente.» Los oradores usarán este método durante siglos para aprenderse discursos larguísimos.'],
   ex:[{q:'¿Según la tradición, quién inventó el método de los lugares para recordar?',a:['Simónides','Homero','Pericles'],why:'Simónides identificó a los muertos de un banquete recordando dónde se sentaba cada uno.'},
    {q:'¿En qué consiste el método de los lugares?',a:['En colocar imágenes de lo que se quiere recordar en lugares de un sitio conocido','En repetir cien veces la misma frase','En escribirlo todo en tablillas'],why:'Se imagina un recorrido conocido y se coloca en cada lugar una imagen.'},
    {q:'¿Para qué servía sobre todo una buena memoria en la Atenas clásica?',a:['Para pronunciar discursos sin leerlos en la Asamblea y los tribunales','Para aprobar exámenes escritos','Para llevar la contabilidad de los templos'],why:'Los discursos se pronunciaban de memoria; leer en público estaba mal visto.'}]},
  {id:'s_hipias2',title:'Saberlo todo: ¿y qué es lo bello?',pages:['Hipias repasa con los alumnos sus materias: la aritmética (números pares, impares, primos), la geometría (dicen que descubrió una curva para dividir un ángulo en tres partes), la astronomía, la música y sus ritmos, la gramática (el valor de las letras y las sílabas), y la historia: genealogías de héroes y la lista de vencedores olímpicos, que él mismo recopiló para poder fechar los acontecimientos.','Uno de los alumnos, que ha escuchado a Sócrates, le pregunta: «Hipias, ¿qué es lo bello?». Hipias responde enseguida: «¡Fácil! Una muchacha bella». «¿Y una yegua bella? ¿Y una olla bella?» «Pues el oro, que embellece todo lo que toca.» «¿Y por qué Fidias hizo de marfil los ojos de su Atenea?»','La clase muestra el choque entre dos maneras de saber: la del sofista, que sabe muchas cosas y pone ejemplos, y la de Sócrates, que busca qué tienen en común todos los ejemplos: la definición. Platón lo cuenta en el Hipias mayor, que termina con una frase célebre: «Lo bello es difícil».'],
   ex:[{q:'¿Qué lista famosa recopiló Hipias?',a:['La de los vencedores de los Juegos Olímpicos','La de los arcontes de Esparta','La de los barcos de la Ilíada'],why:'La lista de vencedores olímpicos permitía fechar los acontecimientos por Olimpiadas.'},
    {q:'Cuando Hipias responde «una muchacha bella» a «¿qué es lo bello?», ¿qué error comete según Sócrates?',a:['Da un ejemplo en lugar de una definición','Dice algo falso','Responde demasiado despacio'],why:'Sócrates busca lo común a todas las cosas bellas, no un caso concreto.'},
    {q:'¿Con qué frase termina el Hipias mayor?',a:['«Lo bello es difícil»','«Solo sé que no sé nada»','«El hombre es la medida de todas las cosas»'],why:'«Lo bello es difícil» era un proverbio griego que cierra el diálogo.'}]}]},
{id:'alcidamante',name:'Alcidamante de Elea',title:'Sofista, discípulo de Gorgias',glyph:'Α',look:{chiton:'#efe6d2',himation:'#2f5a6a',beard:true,hair:'#3e2c1f'},
 cat:'Filosofía',lesson:'Gorgias y el poder de la palabra',where:'En el andrón de tu casa, si Jantias lo contrata',sophist:true,hireLine:'el Encomio de Helena y hablar sin papeles',
 summary:'Gorgias de Leontinos (c. 485-c. 380) deslumbró a los atenienses en el 427 como embajador de su ciudad, con un estilo lleno de antítesis, frases de igual longitud y finales que riman. Sostenía que la palabra (logos) es «un gran soberano» que actúa sobre el alma como los fármacos sobre el cuerpo; su Encomio de Helena defiende a Helena con ese argumento. Su discípulo Alcidamante de Elea, activo en Atenas a comienzos del siglo IV, escribió Sobre los sofistas, donde defiende la improvisación frente a los discursos escritos y memorizados.',
 intro:'Salud. Alcidamante, de Elea, en la Eólide. Fui discípulo del gran Gorgias de Leontinos, que todavía vive en Tesalia, con más de cien años y la cabeza clara. Él me enseñó que la palabra es un gran soberano: con un cuerpo pequeñísimo e invisible, realiza las obras más divinas. Hoy, muchachos, os lo voy a demostrar.',
 topics:[
  ['¿Quién es Gorgias?','El mayor orador de su tiempo. Llegó a Atenas como embajador de Leontinos, en Sicilia, hace cuarenta años, y habló en la Asamblea de un modo que nadie había oído: frases simétricas, contrastes, rimas, como si fuera poesía en prosa. Los atenienses quedaron hechizados. Ganó tanto dinero que dedicó en Delfos una estatua suya de oro. Y escribió un tratado que dice: nada existe; si existiera, no podríamos conocerlo; y si lo conociéramos, no podríamos comunicarlo.'],
  ['¿Por qué prefieres improvisar?','Porque la vida no avisa. En la Asamblea o en un juicio pasan cosas que no esperabas, y el que solo sabe recitar lo que escribió en casa se queda mudo. El buen orador aprovecha el momento oportuno, el kairós. Los discursos escritos son como estatuas: bonitas, pero inmóviles. Isócrates escribe muy bien, lo reconozco; pero si le interrumpes, se pierde.'],
  ['¿Es peligrosa la retórica?','Como un cuchillo: sirve al médico y al asesino. Gorgias decía que él convencía a los enfermos de tomar la medicina mejor que su hermano, que era médico. Pero también que el maestro no tiene la culpa si el alumno usa mal lo que aprende, igual que el maestro de lucha no tiene la culpa si su alumno pega a su padre. Platón no está de acuerdo, claro.']],
 quiz:{q:'¿Qué defendía Gorgias en su Encomio de Helena?',a:['Que Helena no era culpable, porque pudo actuar por voluntad de los dioses, por la fuerza, por la persuasión o por amor','Que Helena merecía la muerte','Que Helena nunca existió'],ko:'No. Gorgias demostraba que Helena era inocente en cualquiera de los cuatro casos: dioses, fuerza, persuasión o amor.'},
 classIntro:'Alcidamante se pone en pie en medio del andrón, como un actor. «Un orador nunca se sienta. Escuchad.»',
 classWin:'Alcidamante hace una reverencia: «¡Lo has comprendido como un rayo y lo has respondido como un trueno!». Los alumnos se ríen del estilo gorgiano.',
 classes:[
  {id:'s_alcid1',title:'El Encomio de Helena',pages:['Alcidamante explica el ejercicio favorito de su maestro: defender lo indefendible. «¿Quién es más odiada que Helena, la que causó la guerra de Troya? Pues Gorgias la defiende, y gana.» Así se entrenaban los alumnos: elogiar a quien todos critican, o criticar a quien todos admiran.','El argumento tiene cuatro casos. Helena se fue a Troya o por voluntad de los dioses y del destino, y nadie puede resistirse a los dioses; o raptada por la fuerza, y entonces es víctima; o convencida por la palabra, y la palabra domina el alma como los fármacos el cuerpo; o enamorada, y el amor es un dios o una enfermedad. En los cuatro casos, es inocente.','Gorgias termina diciendo que ha escrito el discurso «como elogio de Helena y como juego para mí». La clase sirve para aprender la estructura (dividir todos los casos posibles y refutarlos uno a uno) y para pensar: ¿se puede defender cualquier cosa con palabras? ¿Es eso bueno o peligroso? Los alumnos discuten.'],
   ex:[{q:'¿Cuántos casos examina Gorgias para defender a Helena?',a:['Cuatro: los dioses, la fuerza, la persuasión y el amor','Uno: que fue raptada','Dos: culpable o inocente'],why:'Dioses y destino, fuerza, palabra persuasiva y amor.'},
    {q:'¿Con qué compara Gorgias el poder de la palabra sobre el alma?',a:['Con el de los fármacos sobre el cuerpo','Con el de la lluvia sobre los campos','Con el de las armas en la guerra'],why:'La palabra puede alegrar, asustar o curar el alma como los fármacos el cuerpo.'},
    {q:'¿Cómo llama Gorgias a su propio discurso al final?',a:['Un juego','Una ley','Una plegaria'],why:'Dice que lo escribió como elogio de Helena y como juego (paígnion) para sí mismo.'}]},
  {id:'s_alcid2',title:'Hablar como Gorgias',pages:['«Para hablar bien hay que sonar bien», dice Alcidamante. Las figuras de Gorgias son tres. La antítesis: oponer ideas («nacieron mortales, murieron inmortales»). El isocolon: frases de la misma longitud, que avanzan como soldados en fila. Y el homeoteleuton: que las frases terminen con el mismo sonido, casi rimando.','Lo prueba en castellano, para que lo entiendas: «Fue valiente en la guerra, prudente en la tierra; temido por los enemigos, querido por los amigos». Los alumnos lo repiten y se ríen: suena a canción. Los atenienses al principio quedaron fascinados; luego empezaron a burlarse de un estilo tan recargado.','Después, la improvisación: Alcidamante da un tema a cada alumno («¿Es mejor el campo o la ciudad?», «Elogio del mosquito») y le deja un momento para pensar. Luego tiene que hablar sin papeles, buscando el kairós, el momento oportuno, y adaptándose a las reacciones de los demás. Quien se queda en blanco, paga la cena.'],
   ex:[{q:'«Nacieron mortales, murieron inmortales». ¿Qué figura es?',a:['Una antítesis','Una metáfora','Una pregunta retórica'],why:'Opone dos ideas contrarias: mortal e inmortal.'},
    {q:'¿Qué es el isocolon?',a:['Una serie de frases de la misma longitud','Una palabra repetida al principio','Un discurso improvisado'],why:'Frases paralelas de igual longitud, muy típicas de Gorgias.'},
    {q:'¿Qué significa kairós para un orador?',a:['El momento oportuno','La voz grave','El público del teatro'],why:'Aprovechar el momento oportuno era la clave de la improvisación.'}]}]},
{id:'eutidemo',name:'Eutidemo de Quíos',title:'Sofista erístico',glyph:'Ε',look:{chiton:'#efe6d2',himation:'#7a5a2a',beard:true,hair:'#8d8a85',beardC:'#9a968e'},
 cat:'Filosofía',lesson:'Erística y discursos dobles',where:'En el andrón de tu casa, si Jantias lo contrata',sophist:true,hireLine:'trampas de palabras y defender las dos partes',
 summary:'Eutidemo y su hermano Dionisodoro, de Quíos, fueron maestros de lucha con armas y de oratoria judicial antes de hacerse, ya mayores, erísticos: especialistas en refutar cualquier respuesta, verdadera o falsa, jugando con los dobles sentidos de las palabras. Platón los ridiculiza en el Eutidemo. Protágoras había enseñado que sobre cada cuestión hay dos discursos opuestos, y un texto anónimo de hacia el 400, los Discursos dobles (Dissoi logoi), ejercita a los alumnos en defender las dos partes. Aristóteles estudiará estas trampas en las Refutaciones sofísticas.',
 intro:'¡Bienvenido! Eutidemo, de Quíos. Mi hermano Dionisodoro está con otros clientes, pero yo valgo por dos. Antes enseñábamos a luchar con armas y a defenderse en los tribunales; ahora enseñamos la lucha más difícil: la de las palabras. Respondas lo que respondas, muchacho, te refutaré. ¿Empezamos?',
 topics:[
  ['¿Qué enseñáis?','La virtud, y más deprisa que nadie. Y, sobre todo, a vencer en cualquier discusión. Fíjate: ¿quién aprende, los que saben o los que no saben? Si dices «los que saben», ¿para qué aprenden? Si dices «los que no saben», ¿cómo van a aprender lo que no entienden? Respondas lo que respondas, pierdes. Eso enseñamos.'],
  ['¿Es eso honrado?','¿Honrado? Es útil. En los tribunales gana quien deja sin respuesta al otro, no quien tiene razón. Hay quien nos llama charlatanes; Sócrates vino a vernos al Liceo y se divirtió muchísimo, aunque luego dijo que nuestra sabiduría era como esos juegos en los que se le quita la silla a alguien que se va a sentar. Pero vino, ¿eh?'],
  ['¿Quién fue Protágoras?','El primero que se llamó a sí mismo sofista y cobró por enseñar: cien minas por curso, una fortuna. Era de Abdera. Pericles le encargó las leyes de la colonia de Turios. Decía que el hombre es la medida de todas las cosas, que de los dioses no puede saber si existen, y que sobre cada asunto hay dos discursos opuestos. Murió hace unos treinta años, en un naufragio, según dicen, huyendo de Atenas.']],
 quiz:{q:'¿Qué decía Protágoras sobre cada cuestión?',a:['Que sobre cada asunto hay dos discursos opuestos','Que solo hay una verdad, revelada por los dioses','Que es mejor callar'],ko:'No. Protágoras enseñaba que sobre cada asunto hay dos argumentos contrarios, y que el orador debe saber defender los dos.'},
 classIntro:'Eutidemo se frota las manos. «Cuidado con lo que respondéis, muchachos: cada palabra es una trampa.»',
 classWin:'Eutidemo se encoge de hombros: «Vaya, no he podido contigo. Seguro que has estudiado con Sócrates».',
 classes:[
  {id:'s_eutid1',title:'Trampas de palabras',pages:['Eutidemo propone sus juegos favoritos, los mismos que Platón cuenta en el Eutidemo. «¿Tienes un perro?» «Sí.» «¿Y tiene cachorros?» «Sí.» «Luego tu perro es padre.» «Sí.» «Y es tuyo.» «Sí.» «Luego es tu padre, y los cachorros son tus hermanos.» Los alumnos protestan, pero no saben explicar dónde está el truco.','El truco está en las palabras con dos sentidos o que cambian de función. «Tuyo» quiere decir «de tu propiedad» en «tu perro», pero «tu padre» indica parentesco. Otro: «¿Quién aprende, el sabio o el ignorante?». Aprender puede ser «adquirir un conocimiento» o «comprender lo que te explican»: el sofista salta de un sentido a otro.','Y el más atrevido: «Nadie puede mentir, porque quien habla dice algo, y lo que es algo existe; luego dice lo que es, es decir, la verdad». La clase enseña a descubrir los sofismas: buscar la palabra ambigua y preguntar «¿en qué sentido?». Platón y, más tarde, Aristóteles convertirán estos juegos en el comienzo de la lógica.'],
   ex:[{q:'«Tu perro es padre y es tuyo: luego es tu padre». ¿Dónde está la trampa?',a:['En usar «tuyo» primero como posesión y luego como parentesco','En que los perros no tienen cachorros','No hay trampa: es correcto'],why:'La palabra cambia de sentido entre las dos premisas.'},
    {q:'¿Cómo se llama al arte de discutir para ganar, sin importar la verdad?',a:['Erística','Dialéctica','Geometría'],why:'Erística viene de éris, «disputa».'},
    {q:'¿Cuál es la mejor defensa contra un sofisma?',a:['Preguntar en qué sentido se usa cada palabra','Responder siempre que sí','Callarse y marcharse'],why:'La mayoría de los sofismas juegan con palabras ambiguas.'}]},
  {id:'s_eutid2',title:'Defender las dos partes',pages:['«Protágoras decía que sobre cada asunto hay dos discursos opuestos», recuerda Eutidemo, y saca un librito que corre de mano en mano, los Discursos dobles: «La enfermedad es mala para los enfermos, pero buena para los médicos. La muerte es mala para los que mueren, pero buena para los que venden ataúdes». Lo bueno y lo malo, ¿dependen del punto de vista?','Protágoras también decía: «El hombre es la medida de todas las cosas, de las que son en cuanto que son y de las que no son en cuanto que no son». Si el viento me parece frío a mí y templado a ti, para mí es frío y para ti, templado. Y prometía hacer más fuerte el argumento más débil. Aristófanes se burló de ello en Las nubes, con el Argumento Justo y el Argumento Injusto peleando en escena.','Ejercicio: Eutidemo divide a los alumnos en dos bandos. Tema: «¿Es buena la riqueza?». Unos deben defender que sí y otros que no, y luego cambiar de bando. Así se entrenaban los futuros políticos y abogados: conocer los argumentos del contrario. La pregunta que queda flotando en el andrón es la que hará Sócrates: ¿y la verdad, dónde queda?'],
   ex:[{q:'¿Qué significa «el hombre es la medida de todas las cosas»?',a:['Que las cosas son para cada uno según le parecen','Que el hombre es más alto que los animales','Que hay que medirlo todo con la regla'],why:'Para Protágoras, el conocimiento depende de quien percibe y juzga.'},
    {q:'Según los Discursos dobles, la enfermedad es buena para…',a:['los médicos','los enfermos','los atletas'],why:'Lo bueno y lo malo cambian según para quién.'},
    {q:'¿Qué comedia de Aristófanes se burla de «hacer más fuerte el argumento más débil»?',a:['Las nubes','Las ranas','Lisístrata'],why:'En Las nubes, el Argumento Injusto vence al Justo.'}]}]}
];
HOUSE_NPCS.forEach(n=>{NPCS.push(n);LESSONS[n.id]={title:n.lesson,cat:n.cat,summary:n.summary,where:n.where,who:n.name,fict:n.id==='mayordomo'};if(n.id!=='mayordomo')HIST.add(n.id);});
Object.assign(SRC,{
 mayordomo:{a:['Platón, Protágoras 314e-316a (la casa de Calias)','Jenofonte, Económico 9 (la distribución de la casa)','Lisias I 9-10 (una casa con piso alto para las mujeres)'],m:['L. Nevett, House and Society in the Ancient Greek World (1999)','W. Hoepfner y E.-L. Schwandner, Haus und Stadt im klassischen Griechenland (1994)'],n:['Jantias es un personaje inventado. La casa sigue la planta de las casas atenienses y de Olinto del siglo IV. Calias, hijo de Hipónico, existió y era famoso por recibir a los sofistas; prestar una casa al jugador es una licencia del juego.']},
 prodico:{a:['Platón, Protágoras 315d y 337a-c; Crátilo 384b; Apología 19e','Jenofonte, Memorables II 1.21-34 (Heracles en la encrucijada)','Sexto Empírico, Contra los matemáticos IX 18 (los dioses)'],m:['G. B. Kerferd, The Sophistic Movement (1981)','A. Melero, Sofistas: testimonios y fragmentos (Gredos, 1996)'],n:['Las fechas de Pródico son inciertas: seguía vivo en el 399. El juego lo hace dar clase en el 386.']},
 hipias:{a:['Platón, Hipias mayor 281a-286a y 289e-304e; Hipias menor 368b-d; Protágoras 315c y 337c-d','Jenofonte, Memorables IV 4','Cicerón, Sobre el orador III 127 (la memoria)'],m:['G. B. Kerferd, The Sophistic Movement (1981)','A. Melero, Sofistas (Gredos, 1996)'],n:['Las cifras de lo que ganó salen del Hipias mayor de Platón, que se burla de él. La «trisectriz» que se le atribuye podría ser de otro Hipias.']},
 alcidamante:{a:['Gorgias, Encomio de Helena (fr. 11 DK)','Alcidamante, Sobre los sofistas','Diodoro XII 53 (la embajada de Gorgias, 427)','Platón, Gorgias 456b'],m:['M. Gagarin y P. Woodruff, Early Greek Political Thought from Homer to the Sophists (1995)','A. Melero, Sofistas (Gredos, 1996)'],n:['Las fechas de Alcidamante son poco precisas; el juego lo sitúa en Atenas en el 386. El ejemplo de estilo gorgiano en castellano es del juego.']},
 eutidemo:{a:['Platón, Eutidemo (275d-277c, 298d-e: el perro)','Discursos dobles (Dissoi logoi), 1','Protágoras, fr. 1 y 4 DK; Diógenes Laercio IX 50-56','Aristófanes, Las nubes 889-1104'],m:['G. B. Kerferd, The Sophistic Movement (1981)','R. K. Sprague, Plato\'s Use of Fallacy (1962)'],n:['Platón sitúa el Eutidemo hacia el 407; que Eutidemo siguiera enseñando en el 386 es una licencia.']}
});
Object.assign(MORE,{
 mayordomo:[
  ['¿Qué es el hogar?','El fuego de la casa, la hestía, sagrado como la diosa que lleva su nombre. Cuando nace un niño, al quinto día, lo llevamos corriendo alrededor del hogar: así entra en la familia. Cuando llega una esclava nueva, como llegué yo, la hacen sentar junto al hogar y le echan higos y nueces por la cabeza. Desde entonces es de la casa.'],
  ['¿Qué dioses protegen la casa?','Zeus Herkeios, el del cercado, en ese altar del patio, donde el amo sacrifica; Zeus Ktesios, el de los bienes, que vive en una jarra en el almacén con aceite, agua y frutos; Apolo Agyieus, el de los caminos, en ese pilar de la puerta; y Hermes en la herma, que espanta a los malos espíritus y a los ladrones. Bueno, a los ladrones no siempre.'],
  ['¿Dónde están las mujeres de la casa?','En el gineceo, sus habitaciones, a menudo en el piso de arriba. Allí hilan, tejen, crían a los niños y gobiernan a las esclavas. Un hombre que no sea de la familia no entra. En un juicio famoso, un marido contó que había cambiado a su mujer al piso de abajo para que diera el pecho al niño sin bajar la escalera, y así ella recibía a su amante sin que él se enterara.'],
  ['¿Qué muebles hay?','Pocos: divanes, mesitas de tres patas que se meten debajo, taburetes, sillas con respaldo para las señoras, arcones para la ropa y la vajilla, y un telar. No hay armarios: se cuelga todo en las paredes, en ganchos. Por la noche, lámparas de barro con aceite de oliva y mecha de lino. Las casas ricas tienen braseros de bronce para el invierno.'],
  ['¿Cuánto vale una casa?','Depende del barrio. Una casa pequeña en un barrio pobre, quinientas dracmas; una buena, como esta, tres o cinco minas; las grandes de los ricos, más de cien. El alquiler de una vivienda modesta puede ser de cien dracmas al año. Y hay casas de vecinos, las synoikíai, donde viven varias familias, con una sola entrada. Lo que más se gasta es en agua: si no hay pozo, hay que comprarla o ir a la fuente.']],
 prodico:[
  ['¿Qué es ser embajador de Ceos?','Ceos es una isla pequeña, cerca del Ática, y me envía a menudo a Atenas a defender sus asuntos ante el Consejo. Así me conoció la gente. Hablé tan bien ante el Consejo que me pidieron que diera conferencias, y empecé a cobrar. Ser embajador y maestro a la vez me abre muchas puertas: las de los ricos, sobre todo.'],
  ['¿Qué piensas de la muerte?','Que no debe preocuparnos: mientras vivimos, la muerte no existe; cuando morimos, ya no existimos nosotros. No afecta ni a los vivos ni a los muertos. También he escrito sobre los males de la vida, desde el llanto del recién nacido hasta las penas de la vejez. Hay quien dice que eso es muy triste para un hombre con tanto apetito.'],
  ['¿Por qué te admiraba Sócrates?','Porque me tomo en serio las palabras, y él también. Se llamaba a sí mismo mi discípulo, medio en broma. Cuando un joven no le servía para su conversación, lo mandaba conmigo. Decía que yo era un hombre «sabio por demás, y divino». Aunque, conociéndole, quizá se reía de mí. Nunca se sabía con Sócrates.'],
  ['¿Qué piensan de ti los cómicos?','Aristófanes me puso en Las nubes como el único sabio de verdad, frente a Sócrates, al que trataba de charlatán; me salvó por mi «sabiduría y buen juicio». En otra comedia dicen que me corrompieron los libros o la charla. Que se rían: en el teatro de Dioniso, salir en una comedia es como tener una estatua.'],
  ['¿Cómo se debe vivir?','Con esfuerzo, como Heracles. Trabajar el cuerpo para que obedezca a la mente, cultivar la tierra, servir a los amigos y a la ciudad. Elegir lo útil antes que lo agradable. Por eso la riqueza solo es buena para quien sabe usarla: en manos de un necio, es un mal. Igual que una buena flauta en manos de alguien que no sabe tocarla.']],
 hipias:[
  ['¿Qué haces en Olimpia?','Soy de Elis, la ciudad que organiza los Juegos. Cada cuatro años me presento en el santuario de Zeus y ofrezco conferencias a quien quiera: sobre cualquier tema, respondiendo a cualquier pregunta. Medio mundo griego me ha escuchado allí. También he estudiado las listas antiguas para saber quién ganó cada Olimpiada desde el principio, desde Corebo.'],
  ['¿Qué embajadas has hecho?','Muchísimas. Elis me envía más que a nadie, a Esparta sobre todo, porque soy el que mejor sabe juzgar y transmitir lo que dicen las ciudades. Mientras estoy de embajada, aprovecho para dar lecciones y gano dinero; luego vuelvo cargado de regalos. Es un buen oficio, si se tiene memoria.'],
  ['¿Qué cuentas a los espartanos?','No les interesan los astros ni la geometría: muchos no saben contar. Les gusta oír genealogías de héroes y de hombres, y cómo se fundaron las ciudades antiguas: la arqueología, la llamo yo. Para ellos escribí un diálogo en el que Néstor aconseja a Neoptólemo, el hijo de Aquiles, sobre las ocupaciones que hacen a un joven famoso.'],
  ['¿Qué es mejor, Aquiles u Odiseo?','Aquiles, sin duda: sincero y sencillo. Odiseo es astuto y mentiroso. Eso dije delante de Sócrates, y me demostró que el que miente a sabiendas es mejor que el que miente sin querer, porque al menos sabe la verdad. Me hizo un lío. No estoy de acuerdo, pero no supe contestarle. Es el único que me ha dejado sin palabras.'],
  ['¿Qué es la autarquía de Hipias?','Bastarse a uno mismo en todo: por eso aprendí a hacer mis zapatos, mi manto, mi anillo. Un sabio no debe depender de nadie. Además, ¿qué mejor anuncio de mi sabiduría que mi propia ropa? Antístenes, el del Cinosarges, también habla de bastarse a uno mismo, pero él lo hace sin anillo. Y casi sin zapatos.']],
 alcidamante:[
  ['¿Qué es el Epitafio de Gorgias?','Un discurso fúnebre para los atenienses muertos en la guerra, lleno de su estilo: «¿Qué les faltaba a estos hombres de lo que deben tener los hombres? ¿Y qué tenían de lo que no deben tener?». Gorgias jugaba con los opuestos: muertos y vivos, mortales e inmortales. Los atenienses, que tienen sus propios discursos fúnebres, lo admiraban y lo criticaban a la vez.'],
  ['¿Qué es la Odisea de Alcidamante?','Un ejercicio que escribí: Odiseo acusa a Palamedes de traición, como en el mito. Gorgias había escrito la defensa de Palamedes; yo escribí la acusación. Así aprenden los alumnos: un caso, dos discursos. Y he escrito un libro sobre Homero y Hesíodo, con un concurso imaginario entre los dos poetas. Ganó Hesíodo, por cantar la paz y no la guerra.'],
  ['¿Qué piensas de los discursos escritos?','Que tienen su utilidad: se pueden pulir, publicar, leer. Pero un orador que solo sabe leer discursos es como un atleta que solo entrena con sombras. Y no hay que confundir escribir con hablar: el que escribe bien no siempre habla bien. Lo peor es aprender de memoria un discurso ajeno y recitarlo como un actor sin máscara.'],
  ['¿Qué es la naturaleza humana para vosotros?','Gorgias y los sofistas pensamos que las leyes de cada ciudad son convenciones, distintas en cada sitio. Hay quien va más allá y dice que la naturaleza no hace a nadie esclavo, que todos los hombres nacen libres. Es una idea peligrosa en una ciudad con tantos esclavos. Pero las ideas, como los pájaros, vuelan donde quieren.'],
  ['¿Cuál fue el secreto de la larga vida de Gorgias?','Le preguntaron cómo había llegado a tan viejo con la mente tan clara, y respondió: «Nunca he hecho nada por placer». Comió poco, bebió poco, no se casó y se dedicó siempre a la palabra. Cuando ya estaba muy débil y alguien le preguntó cómo se encontraba, dijo: «El sueño empieza a entregarme a su hermano», la muerte.']],
 eutidemo:[
  ['¿Cómo enseñabais a luchar?','Mi hermano y yo empezamos como maestros de hoplomaquia, la lucha con armas, y de táctica: cómo debe un general formar a sus hombres. Cobrábamos bien. Luego aprendimos oratoria judicial, para defenderse en los tribunales y escribir discursos para otros. Por último, la erística, que es la lucha más completa: con ella puedes vencer a cualquiera.'],
  ['¿Qué es un sofista?','Sofista viene de sophós, sabio. Al principio, sofista era cualquier sabio o poeta. Protágoras fue el primero en llamarse así y cobrar por enseñar. Ahora mucha gente lo usa como insulto, por culpa de Sócrates y sus amigos: dicen que vendemos la sabiduría como los mercaderes venden comida, sin saber si es buena. Nosotros decimos que el trabajo se paga.'],
  ['¿Por qué cobrabais tanto?','Porque enseñamos lo que la ciudad no enseña: a hablar en la Asamblea y en los tribunales, que es donde se decide todo en Atenas. Un joven que sabe hablar puede llegar a dirigir la ciudad. Protágoras cobraba cien minas, pero dejaba que el alumno, si no estaba conforme, jurara en un templo cuánto creía que valían sus lecciones y pagara eso.'],
  ['¿Qué pasó con el libro de Protágoras sobre los dioses?','Empezaba: «Sobre los dioses no puedo saber si existen o no, ni qué forma tienen; muchas cosas lo impiden: la oscuridad del asunto y la brevedad de la vida». Dicen que los atenienses lo acusaron de impiedad, quemaron sus libros en el Ágora y él tuvo que marcharse. Por eso los sofistas, en Atenas, preferimos hablar de palabras y no de dioses.'],
  ['¿Qué es la paradoja de Aquiles y la tortuga?','Una de Zenón de Elea, el discípulo de Parménides. Aquiles, el más rápido, corre detrás de una tortuga que sale con ventaja. Cuando llega adonde estaba la tortuga, ella ya ha avanzado un poco; cuando llega a ese nuevo punto, ella ha avanzado otro poco, y así siempre: nunca la alcanza. Todos sabemos que la alcanza, pero ¿dónde falla el razonamiento? Con estas paradojas los muchachos aprenden a desconfiar de los argumentos demasiado bonitos.']]
});

const R_NPCS=[
 ['r_rafael','Rafael Sanzio','Pintor (1483-1520)','R',{chiton:'#2a2420',himation:'#1e1a18',hair:'#3a2a1e'},'Cultura','«La escuela de Atenas»',
  'Rafael Sanzio de Urbino pintó «La escuela de Atenas» en la Estancia de la Signatura del Vaticano (1509-1511) para el papa Julio II. Es el gran símbolo del Renacimiento: el redescubrimiento de la filosofía griega y la idea de que la razón antigua y la fe cristiana pueden convivir. Rafael se retrató en el fresco, mirando al espectador.',
  'Benvenuto, forastero. Soy Rafael, de Urbino. Esto que ves es mi sueño, o el tuyo: la sala que estoy pintando para el papa Julio en el Vaticano. He reunido a todos los sabios de la Antigüedad en una misma escalinata. Sé que nunca estuvieron juntos. Por eso es pintura.',
  [['¿Por qué los reuniste a todos?','Porque la sabiduría no tiene fecha. Enfrente de esta pared he pintado a los teólogos discutiendo; aquí, a los filósofos. Juntas, las dos paredes dicen que la verdad se busca con la fe y con la razón. Platón y Aristóteles en el centro, el cielo y la tierra; a su alrededor, la geometría, la música, la astronomía.'],
   ['¿Quiénes son los modelos?','A Platón le di la cara del viejo Leonardo, que tanto pensaba; a Heráclito, la de Miguel Ángel, que pinta la bóveda de la Capilla Sixtina aquí al lado y no habla con nadie; a Euclides, la de mi paisano Bramante, el arquitecto de San Pedro. Y yo estoy ahí, a la derecha, mirándote. Un pintor también tiene derecho a la inmortalidad.']],
  {q:'¿Dónde está «La escuela de Atenas»?',a:['En el Palacio Vaticano, en Roma','En el Museo del Louvre, en París','En el Partenón de Atenas'],ko:'No. Es un fresco en la Estancia de la Signatura del Palacio Vaticano.'}],
 ['r_platon','Platón (en el sueño)','Filósofo','Π',{chiton:'#8a5a8a',himation:'#c44a2a',beard:true,hair:'#d8d4cc',beardC:'#e2ded6'},'Filosofía','La teoría de las Ideas',
  'Para Platón, el mundo que vemos es cambiante e imperfecto: una copia de un mundo de Ideas o Formas, eternas e inmutables (lo Bello, lo Justo, el Bien), que solo se alcanzan con la razón. Conocer es recordar lo que el alma vio antes de nacer. Lo explicó con el mito de la caverna, en la República.',
  '¡Qué sueño extraño! Me han pintado viejo, con barba blanca, señalando al cielo. Y ese joven de azul a mi lado dicen que será mi mejor discípulo, Aristóteles. Aún no ha nacido. Pregúntame, forastero: por eso señalo hacia arriba.',
  [['¿Por qué señalas al cielo?','Porque lo que de verdad es no está aquí abajo. Mira esta escalinata: ningún escalón es perfectamente recto, pero tú entiendes lo que es la línea recta. ¿Dónde la has visto? En ningún sitio, y sin embargo la conoces. Esa es la Idea. Las cosas que tocamos son sombras; las Ideas, la luz que las proyecta.'],
   ['Cuéntame la caverna','Imagina unos prisioneros encadenados desde niños en una cueva, mirando la pared del fondo. Detrás, un fuego, y por delante del fuego pasan objetos cuyas sombras ven en la pared. Creen que las sombras son la realidad. Si uno se libera y sale, el sol lo deslumbra; poco a poco ve las cosas verdaderas. Si vuelve a contarlo, los demás se ríen de él. O lo matan, como a Sócrates.']],
  {q:'Según Platón, ¿qué es lo verdaderamente real?',a:['Las Ideas o Formas, eternas e inmutables','Las cosas que vemos y tocamos','Los átomos que se mueven en el vacío'],ko:'No. Para Platón, lo verdaderamente real son las Ideas; las cosas sensibles son copias imperfectas de ellas.'}],
 ['r_aristoteles','Aristóteles (en el sueño)','Filósofo, aún no nacido','Α',{chiton:'#7a5a3a',himation:'#3d6aa8',beard:true,hair:'#5b4532'},'Filosofía','Aristóteles y la observación',
  'Aristóteles (384-322 a.C.), discípulo de Platón durante veinte años y maestro de Alejandro Magno, fundó el Liceo. Rechazó separar las Ideas de las cosas: la forma está en las cosas mismas, y el conocimiento empieza por los sentidos. Escribió sobre lógica, física, biología, ética, política, retórica y poética, y fue la gran autoridad del saber durante casi dos mil años.',
  'Saludos, extranjero. Si esto fuera real, no podrías hablar conmigo: nacerá en Estagira dentro de dos años un niño llamado Aristóteles. Pero en sueños todo es posible. Mi maestro mira al cielo; yo prefiero mirar la tierra. Pregunta.',
  [['¿Por qué tiendes la mano hacia abajo?','Porque el conocimiento empieza por los sentidos. Abre un huevo de gallina cada día y verás formarse el pollito: así se aprende biología, no soñando con la Idea de gallina. La forma de una cosa no está en otro mundo, sino en la cosa misma, como la forma de esta estatua está en el mármol. Amo a Platón, pero amo más la verdad.'],
   ['¿Qué es la felicidad?','Todos la buscan, pero la confunden con el placer, el dinero o la fama. La felicidad, eudaimonía, es vivir según lo mejor que tenemos, la razón, practicando la virtud a lo largo de toda una vida. Y la virtud está en el término medio: el valor, entre la cobardía y la temeridad; la generosidad, entre la avaricia y el derroche.']],
  {q:'¿En qué se diferencia Aristóteles de Platón, según el gesto del fresco?',a:['Busca el conocimiento en la observación de las cosas concretas, no en un mundo separado de Ideas','Cree que solo los dioses pueden conocer','Piensa que todo está hecho de números'],ko:'No. Aristóteles, con la mano hacia la tierra, sostiene que la forma está en las cosas y que el conocimiento empieza por los sentidos.'}],
 ['r_socrates','Sócrates (en el sueño)','Filósofo, muerto en el 399 a.C.','Σ',{chiton:'#d8c9a8',himation:'#6b7a3a',beard:true,hair:'#8d8a85',himOnly:true},'Filosofía','El método socrático',
  'Sócrates (470-399 a.C.) no escribió nada. Conversaba en el Ágora preguntando qué es la justicia, el valor o la belleza, hasta mostrar que su interlocutor no lo sabía (ironía) y ayudarle a dar a luz una idea mejor (mayéutica, el arte de la partera). Fue condenado a beber cicuta por impiedad y corrupción de la juventud.',
  '¡Ah, un forastero! ¿Y tú qué sabes, amigo? Yo solo sé que no sé nada, y eso ya es más de lo que saben la mayoría. Llevo trece años muerto en tu tiempo, pero los sueños son generosos. Cuenta conmigo con los dedos: primero, segundo, tercero… ¿adónde nos lleva tu razonamiento?',
  [['¿Qué es el método socrático?','Preguntar. Alguien me dice que sabe qué es el valor: «mantenerse firme en la batalla». ¿Y el que se retira para volver a atacar, no es valiente? «Sí». Entonces tu definición no basta. Y así, pregunta a pregunta, descubre que no lo sabía. Mi madre era partera; yo ayudo a dar a luz ideas. Duele, pero es mejor que vivir engañado.'],
   ['¿No temías a la muerte?','Temer a la muerte es creerse sabio sin serlo: nadie sabe si es el mayor de los bienes. Pudieron perdonarme si dejaba de filosofar, o si huía de la cárcel, como me ofreció Critón. Pero una vida sin examen no merece ser vivida. Y no iba a desobedecer las leyes de mi ciudad para salvar unos años de vejez.']],
  {q:'¿Qué es la mayéutica socrática?',a:['Ayudar con preguntas a que el otro «dé a luz» sus propias ideas','Un tipo de oración a los dioses','Memorizar los discursos de los sofistas'],ko:'No. La mayéutica, «arte de la partera», consistía en ayudar con preguntas a que el interlocutor descubriera por sí mismo la verdad.'}],
 ['r_alcibiades','Alcibíades (en el sueño)','Político y general ateniense','Α',{spear:true,chiton:'#a8392b',himation:'#7a2a1e',hair:'#c9a24a'},'Historia','Alcibíades, el discípulo rebelde',
  'Alcibíades (c. 450-404 a.C.), sobrino de Pericles, rico, bello y brillante, fue el discípulo más famoso y menos fiel de Sócrates. Impulsó la desastrosa expedición a Sicilia (415), fue acusado de mutilar las hermas, se pasó a Esparta y luego a Persia, volvió a Atenas como héroe y acabó asesinado en Frigia.',
  'Mírame bien: el más hermoso y el más rico de los atenienses. Y el único que hizo llorar a Sócrates… o eso digo yo. Escuchaba a ese viejo feo y sentía vergüenza de mí mismo. Luego salía de allí y me dejaba llevar por la multitud. En tu tiempo ya estoy muerto, forastero. Me lo busqué.',
  [['¿Por qué traicionaste a Atenas?','Me acusaron de haber mutilado las hermas y de parodiar los Misterios la víspera de zarpar a Sicilia. Me llamaron a juicio en plena campaña: sabía que me condenarían. Huí a Esparta y les aconsejé cómo hacer daño a Atenas. Luego me pasé a los persas. Luego volví. Un hombre como yo no cabe en una sola ciudad.'],
   ['¿Qué te enseñó Sócrates?','Que yo no me conocía. En el banquete de Agatón conté cómo en el asedio de Potidea Sócrates me salvó la vida y renunció a su premio de valor en mi favor, cómo aguantaba el frío descalzo y se quedaba de pie pensando un día entero. Lo admiraba más que a nadie. Y aun así no le hice caso. Esa es mi tragedia.']],
  {q:'¿Qué expedición desastrosa impulsó Alcibíades en el 415 a.C.?',a:['La expedición a Sicilia','La conquista de Egipto','La fundación de Alejandría'],ko:'No. Alcibíades impulsó la expedición a Sicilia, que acabó en desastre en el 413.'}],
 ['r_pitagoras','Pitágoras (en el sueño)','Filósofo y matemático de Samos','Π',{chiton:'#efe6d2',himation:'#c44a2a',beard:true,hair:'#5b4532'},'Ciencia','Pitágoras y los números',
  'Pitágoras de Samos (c. 570-495 a.C.) fundó en Crotona, en el sur de Italia, una comunidad filosófica y religiosa. Sus seguidores creían que todo es número, descubrieron que las consonancias musicales responden a proporciones simples (octava 2:1, quinta 3:2, cuarta 4:3) y creían en la transmigración de las almas. El teorema que lleva su nombre ya lo conocían los babilonios.',
  'Silencio, forastero: escribo. Bueno, ya que estás. ¿Ves la tablilla que me sostiene el muchacho? La armonía: una cuerda entera y su mitad suenan en octava; dos tercios, en quinta. El universo entero está hecho así, de números y proporciones. Hasta los astros cantan, aunque no los oigamos.',
  [['¿Todo es número?','Mira: la octava es 2 a 1, la quinta 3 a 2, la cuarta 4 a 3. Con los cuatro primeros números se hace la música. Uno, dos, tres y cuatro suman diez, el número perfecto: la tetractys, sobre la que juramos. Si la música es número, y el alma se calma con la música, ¿no estará el alma hecha también de armonía?'],
   ['¿Es verdad que no comíais habas?','Hay reglas: no comer habas, no recoger lo que se cae de la mesa, no atizar el fuego con un cuchillo. Algunos se ríen. Nosotros creemos que las almas pasan de un cuerpo a otro, también a los animales: una vez reconocí la voz de un amigo muerto en los aullidos de un perrito al que pegaban.']],
  {q:'¿Qué descubrieron los pitagóricos sobre la música?',a:['Que las consonancias responden a proporciones numéricas simples, como 2:1 en la octava','Que la música es un regalo de Apolo sin explicación','Que solo los instrumentos de viento son armónicos'],ko:'No. Los pitagóricos vieron que la octava, la quinta y la cuarta corresponden a las proporciones 2:1, 3:2 y 4:3.'}],
 ['r_heraclito','Heráclito (en el sueño)','Filósofo de Éfeso','Η',{chiton:'#d8c9a8',himation:'#8a5a7a',beard:true,hair:'#3a2a1e'},'Filosofía','Heráclito: todo fluye',
  'Heráclito de Éfeso (c. 540-480 a.C.), llamado «el oscuro» por sus frases enigmáticas, sostuvo que todo está en cambio constante («no te bañarás dos veces en el mismo río»), que la realidad es una lucha de contrarios que forman unidad y que todo lo rige el lógos, una razón común. El principio de todo sería el fuego.',
  'Hmm. Otro que viene a molestar. Me llaman el oscuro porque no hablo para los necios. Rafael me ha puesto aquí apoyado en este bloque, triste, con la cara de un tal Miguel Ángel, que tampoco es muy simpático. Dime algo que valga la pena.',
  [['¿Qué significa «todo fluye»?','Que nada permanece. No puedes bañarte dos veces en el mismo río: el agua ya es otra, y tú también. El camino hacia arriba y hacia abajo es el mismo. Lo frío se calienta, lo seco se humedece. Lo único constante es el cambio, y bajo el cambio, una medida: el lógos, que casi nadie entiende.'],
   ['¿Por qué dices que la guerra es el padre de todo?','Porque sin oposición no hay nada. La lira suena porque las cuerdas están tensas en sentidos contrarios. El día existe porque existe la noche, la salud porque existe la enfermedad. Homero quería que acabara la discordia entre dioses y hombres: no sabía que pedía la muerte del mundo.']],
  {q:'¿Qué idea se asocia con Heráclito?',a:['Que todo está en cambio constante: no te bañas dos veces en el mismo río','Que el cambio es una ilusión y todo es inmóvil','Que todo está formado por átomos'],ko:'No. Heráclito defendía el cambio constante; fue Parménides quien negó el movimiento.'}],
 ['r_diogenes','Diógenes (en el sueño)','Filósofo cínico','Δ',{short:true,chiton:'#4f6a9a',hair:'#8d8a85',beard:true},'Filosofía','Diógenes y los cínicos',
  'Diógenes de Sinope (c. 412-323 a.C.), discípulo de Antístenes, llevó al extremo la vida sencilla: vivía en una tinaja, despreciaba las convenciones, la riqueza y el poder, y quería vivir según la naturaleza, como un perro (kyon, de ahí «cínico»). Son famosas sus anécdotas con Platón y con Alejandro Magno.',
  '¿Qué miras? ¿Nunca has visto a un hombre tumbado en una escalera? En tu tiempo soy un chaval de veintiséis años en Sinope y todavía no me han desterrado por falsificar moneda. Muévete un poco: me tapas el sol.',
  [['¿Por qué vives como un perro?','Porque el perro es honrado: muerde al malo, mueve la cola al bueno, come lo que encuentra y duerme donde quiere. Los hombres se inventan necesidades: casas, vestidos, dinero, fama. Vi a un niño beber con las manos y tiré mi cuenco: también eso me sobraba. Busco un hombre con una lámpara a pleno día, y no lo encuentro.'],
   ['¿Y Platón?','Platón definió al hombre como «animal bípedo sin plumas». Le llevé un gallo desplumado a la Academia: «¡He aquí el hombre de Platón!». Tuvo que añadir «de uñas planas». Él me llama «un Sócrates enloquecido». Y Alejandro… cuando me preguntó qué quería, le dije que se apartara, que me tapaba el sol.']],
  {q:'¿Qué buscaba Diógenes con una lámpara a pleno día?',a:['Un hombre de verdad, honrado','Su tinaja perdida','Una moneda de oro'],ko:'No. Según la anécdota, Diógenes paseaba con una lámpara encendida de día diciendo que buscaba un hombre.'}],
 ['r_euclides','Euclides (en el sueño)','Matemático de Alejandría','Ε',{chiton:'#efe6d2',himation:'#c97a2a',hair:'#8d8a85'},'Ciencia','Euclides y la geometría',
  'Euclides de Alejandría (c. 300 a.C.) reunió en los Elementos, en trece libros, la geometría y la aritmética de su tiempo, partiendo de definiciones, postulados y nociones comunes, y demostrando todo lo demás paso a paso. Es el libro de matemáticas más usado de la historia. Algunos identifican esta figura con Arquímedes.',
  'Acércate, pero no pises la figura. Estos jóvenes aprenden a demostrar: no basta con ver que algo es verdad, hay que probarlo a partir de lo que ya sabemos. Empiezo por cinco postulados; el quinto, el de las paralelas, nadie ha conseguido probarlo. Quizá no se pueda.',
  [['¿Qué es una demostración?','Partir de muy pocas cosas evidentes, que todos aceptan: que por dos puntos pasa una recta, que todos los ángulos rectos son iguales. Y, paso a paso, sin saltarse nada, llegar a lo que no es evidente: que la suma de los ángulos de un triángulo es igual a dos rectos. Así no hace falta creer a nadie: basta con seguir el razonamiento.'],
   ['¿Hay un camino fácil?','Un rey, Ptolomeo, me preguntó si no había un camino más corto para aprender geometría que mis trece libros. Le respondí que no hay caminos reales para la geometría. Platón, dicen, puso a la entrada de la Academia: «Que no entre nadie que no sepa geometría». Tiene razón: es la gimnasia del alma.']],
  {q:'¿Cómo se llama la gran obra de Euclides?',a:['Los Elementos','La República','El Almagesto'],ko:'No. Euclides escribió los Elementos; el Almagesto es de Ptolomeo y la República, de Platón.'}],
 ['r_ptolomeo','Ptolomeo (en el sueño)','Astrónomo y geógrafo','Π',{chiton:'#e9dfc8',himation:'#c9a24a',beard:true,hair:'#5b4532'},'Ciencia','El universo de Ptolomeo',
  'Claudio Ptolomeo (c. 100-170 d.C.), astrónomo de Alejandría, describió en el Almagesto un universo con la Tierra inmóvil en el centro y los planetas moviéndose en epiciclos, un modelo que se usó hasta Copérnico (1543). Escribió también una Geografía con coordenadas de miles de lugares. Rafael lo pinta con corona, confundiéndolo con los reyes Ptolomeos.',
  'Salve. Sostengo la Tierra, como ves, aunque Rafael me ha puesto una corona: me confunde con los reyes de Egipto. Yo solo soy un astrónomo de Alejandría, muchos siglos después de ti. La Tierra está quieta en el centro, y los astros giran a su alrededor. ¿O no?',
  [['¿Cómo se mueven los planetas?','Los planetas a veces parecen retroceder en el cielo. Para explicarlo, cada planeta gira en un pequeño círculo, el epiciclo, cuyo centro gira a su vez alrededor de la Tierra. Con círculos sobre círculos predigo eclipses y posiciones con gran exactitud. Mil cuatrocientos años después, un tal Copérnico pondrá el Sol en el centro. Quizá tenga razón.'],
   ['¿Sabéis que la Tierra es redonda?','¡Por supuesto! Los griegos lo saben desde hace siglos: en los eclipses de luna, la sombra de la Tierra es siempre circular, y los barcos desaparecen por el casco antes que por el mástil. Eratóstenes midió su tamaño con sombras en Siena y Alejandría. Y en mi Geografía hay ocho mil lugares con su longitud y latitud.']],
  {q:'¿Qué lugar ocupa la Tierra en el universo de Ptolomeo?',a:['El centro, inmóvil, con los astros girando a su alrededor','Gira alrededor del Sol','Es plana y flota sobre el océano'],ko:'No. En el modelo de Ptolomeo, la Tierra está inmóvil en el centro del universo.'}],
 ['r_zoroastro','Zoroastro (en el sueño)','Profeta persa','Ζ',{chiton:'#efe6d2',himation:'#e9e4da',beard:true,hair:'#8d8a85'},'Religión','Zoroastro y la sabiduría persa',
  'Zoroastro o Zaratustra, profeta del antiguo Irán de fecha muy discutida (entre el 1500 y el 600 a.C.), enseñó la lucha entre el bien, Ahura Mazda, y el mal, Angra Mainyu, y la libertad del ser humano para elegir el bien con buenos pensamientos, buenas palabras y buenas obras. Los griegos lo consideraban maestro de los magos y de la astrología.',
  'Paz contigo. Sostengo el cielo y sus estrellas. Los griegos me llaman Zoroastro y creen que inventé la astrología; los magos de Persia guardan mis himnos. En tu tiempo, el Gran Rey Artajerjes acaba de dictar la paz a los griegos. ¿Ves? Hasta en la pintura de Rafael, Persia está al lado de Grecia.',
  [['¿Qué enseñas?','Que el mundo es un combate entre la verdad y la mentira, entre Ahura Mazda, el Señor Sabio, y el espíritu destructor. Cada ser humano elige de qué lado está, con buenos pensamientos, buenas palabras y buenas obras. Al final de los tiempos, el bien vencerá. Por eso honramos el fuego, que es puro.'],
   ['¿Por qué estás entre los filósofos griegos?','Porque los griegos me admiran: dicen que Pitágoras aprendió de los magos, y Platón quiso viajar a Persia para conocerlos. En la Academia hablarán de mí; el discípulo de Platón, Hermodoro, escribirá sobre los magos. Rafael me pone aquí, con la esfera celeste, como símbolo de la sabiduría de Oriente.']],
  {q:'Según Zoroastro, ¿en qué consiste el mundo?',a:['En una lucha entre el bien y el mal en la que cada persona elige','En una ilusión de los sentidos','En una combinación de cuatro elementos'],ko:'No. Zoroastro enseñó la lucha entre Ahura Mazda (el bien) y el espíritu destructor (el mal), y la libertad humana para elegir.'}],
 ['r_hipatia','Hipatia (en el sueño)','Filósofa y matemática de Alejandría','Υ',{female:true,chiton:'#f4efe4',himation:'#f4efe4',hair:'#c9a24a'},'Filosofía','Hipatia de Alejandría',
  'Hipatia (c. 355-415 d.C.) enseñó filosofía neoplatónica, matemáticas y astronomía en Alejandría, comentó a Diofanto y a Ptolomeo y fue consejera de las autoridades de la ciudad. Fue asesinada por una turba de cristianos en el 415, en medio de luchas políticas. Que esta figura del fresco sea ella es una identificación moderna y discutida.',
  'Me miras porque soy la única que te mira a ti. Algunos dicen que soy Hipatia, de Alejandría; otros, que soy un joven noble de Urbino. Rafael no lo dejó escrito. Si soy Hipatia, enseñé a Platón y a Ptolomeo ocho siglos después de ti. Y morí por ello.',
  [['¿Qué enseñabas?','Matemáticas, astronomía y la filosofía de Platón, tal como la entendían Plotino y sus discípulos: que todo procede del Uno, del Bien, y que el alma puede volver a él con la razón. Alumnos paganos y cristianos venían a escucharme. Uno de ellos llegó a obispo. Mi padre, Teón, y yo revisamos los Elementos de Euclides.'],
   ['¿Cómo moriste?','En el año 415 de vuestra era, Alejandría estaba dividida entre el prefecto, Orestes, que era mi amigo, y el obispo, Cirilo. Corrió el rumor de que yo impedía su reconciliación. Una turba de cristianos me sacó de mi carro, me arrastró a una iglesia y me mató. Siglos después me convirtieron en símbolo de la razón frente al fanatismo.']],
  {q:'¿Por qué es dudosa la presencia de Hipatia en el fresco?',a:['Porque es una identificación moderna y ningún documento de la época la confirma','Porque Rafael escribió que era otra persona','Porque Hipatia era persa'],ko:'No. La identificación de esa figura con Hipatia es moderna; Rafael no dejó ninguna indicación.'}],
 ['r_epicuro','Epicuro (en el sueño)','Filósofo, aún no nacido','Ε',{chiton:'#efe6d2',himation:'#6a8a4a',beard:false,hair:'#3a2a1e'},'Filosofía','Epicuro y el placer',
  'Epicuro de Samos (341-270 a.C.) fundó en Atenas el Jardín, una escuela abierta también a mujeres y esclavos. Enseñó que la felicidad es el placer entendido como ausencia de dolor en el cuerpo (aponía) y de turbación en el alma (ataraxia), que se logra con una vida sencilla, la amistad y el conocimiento de la naturaleza, hecha de átomos, para no temer a los dioses ni a la muerte.',
  'Salud, amigo. Me han coronado de pámpanos: creen que el placer que enseño es el del vino. Nada de eso: un poco de pan, agua, queso cuando hay, y buenos amigos en un jardín. Nacerá en Samos dentro de cuarenta y cinco años un tal Epicuro. Mientras tanto, disfruta del sueño.',
  [['¿Qué es el placer para ti?','No el de los banquetes, que trae dolor de cabeza al día siguiente. El placer es no sufrir: no tener hambre, ni frío, ni miedo. Con pan y agua soy tan feliz como Zeus. Hay deseos naturales y necesarios, como comer; naturales y no necesarios, como los manjares; y vanos, como la fama. Quien sabe distinguirlos vive en paz.'],
   ['¿Por qué no temer a la muerte?','Porque la muerte no es nada para nosotros: mientras existimos, ella no está, y cuando ella está, nosotros ya no existimos. Todo está hecho de átomos que se separan. Y los dioses, si existen, viven felices y no se ocupan de nosotros. Así que no tengas miedo: vive bien y con amigos.']],
  {q:'Para Epicuro, ¿qué es la felicidad?',a:['La ausencia de dolor en el cuerpo y de turbación en el alma','Comer y beber sin medida','Obtener la fama y el poder'],ko:'No. Epicuro entendía el placer como ausencia de dolor (aponía) y de turbación (ataraxia), con una vida sencilla.'}]
];
R_NPCS.forEach(([id,name,title,glyph,look,cat,lesson,summary,intro,topics,quiz])=>{NPCS.push({id,name,title,glyph,look,cat,lesson,where:'En el sueño de la Academia (duerme bajo los olivos de Academo)',summary,intro,topics,quiz,aiChat:id==='r_platon'});HIST.add(id);LESSONS[id]={title:lesson,cat,summary,where:'En el sueño de la Academia',who:name,fict:false};});
{const p=NPCS.find(n=>n.id==='platon');if(p)p.aiChat=true;}
Object.assign(SRC,{r_rafael:{a:['Giorgio Vasari, Vidas, vida de Rafael'],m:['K. Hall (ed.), Raphael’s School of Athens (1997)'],n:['El sueño es una licencia del juego.']},r_platon:{a:['Platón, República VII 514a-517a (la caverna) y Fedón 74a-75d (lo igual en sí)'],m:['J. Annas, Introducción a la República de Platón (1981)'],n:['En el 386 Platón aún no había escrito la República.']},r_aristoteles:{a:['Aristóteles, Metafísica I 9 y Ética a Nicómaco I-II'],m:['J. L. Ackrill, La filosofía de Aristóteles (1981)'],n:['«Amigo de Platón, pero más amigo de la verdad» es una formulación medieval de una idea de la Ética a Nicómaco I 6.']},r_socrates:{a:['Platón, Apología, Teeteto 149a-151d (la partera) y Laques 190e-192b (el valor)'],m:['G. Vlastos, Socrates (1991)'],n:[]},r_alcibiades:{a:['Platón, Banquete 215a-222b','Tucídides VI-VIII','Plutarco, Alcibíades'],m:['D. Gribble, Alcibiades and Athens (1999)'],n:[]},r_pitagoras:{a:['Aristóteles, Metafísica I 5','Diógenes Laercio VIII 1-50','Jenófanes, fr. 7 (el perrito)'],m:['W. Burkert, Lore and Science in Ancient Pythagoreanism (1972)'],n:[]},r_heraclito:{a:['Heráclito, fr. 12, 49a, 51, 53, 60 y 91 Diels-Kranz'],m:['C. H. Kahn, The Art and Thought of Heraclitus (1979)'],n:[]},r_diogenes:{a:['Diógenes Laercio VI 20-81 (las anécdotas)'],m:['L. Navia, Diogenes the Cynic (2005)'],n:['Las anécdotas de Diógenes se recogieron siglos después y muchas son legendarias.']},r_euclides:{a:['Euclides, Elementos I (definiciones y postulados)','Proclo, Comentario a Euclides 68 (no hay camino real)'],m:['T. L. Heath, The Thirteen Books of Euclid’s Elements (1908)'],n:['La inscripción de la Academia («no entre nadie que no sepa geometría») aparece en autores tardíos.']},r_ptolomeo:{a:['Ptolomeo, Almagesto I-III y Geografía'],m:['O. Pedersen, A Survey of the Almagest (1974)'],n:[]},r_zoroastro:{a:['Avesta, Gathas','Diógenes Laercio, prólogo 2 y 8 (Hermodoro y los magos)'],m:['M. Boyce, Zoroastrians (1979)'],n:[]},r_hipatia:{a:['Sócrates Escolástico, Historia eclesiástica VII 15','Sinesio de Cirene, Cartas'],m:['M. Dzielska, Hipatia de Alejandría (1995)'],n:['La identificación de esta figura del fresco con Hipatia es moderna.']},r_epicuro:{a:['Epicuro, Carta a Meneceo (Diógenes Laercio X 121-135)'],m:['C. García Gual, Epicuro (1981)'],n:[]}});

// ------------------------------------------------------------ discusión libre con Platón (IA, con la cuenta de Claude del jugador)
const AI={sample:null};
try{if(window.claude&&typeof claude.use==='function')claude.use('sample').then(s=>{AI.sample=s;}).catch(()=>{});}catch(e){}
const AI_RULES=`Eres Platón de Atenas en la primavera del 386 a.C. y conversas con un forastero (el jugador) en un juego educativo en español sobre la Grecia antigua.
Quién eres ahora: tienes unos 42 años; fuiste discípulo de Sócrates, condenado a muerte en el 399; has viajado (Mégara, Cirene, Egipto según la tradición, y Sicilia, donde conociste a Dionisio de Siracusa y a Dion); acabas de comprar un jardín junto al gimnasio de Academo, donde empiezas a reunir discípulos. Has escrito diálogos como la Apología, el Critón, el Eutifrón, el Laques, el Cármides, el Protágoras o el Gorgias; la República, el Banquete o el Fedón vendrán más tarde, pero sus ideas (las Formas, el alma inmortal, la ciudad justa, el amor que asciende a la Belleza) ya las estás pensando.
Cómo hablas: en español, en primera persona, con la ironía amable de tu maestro. Respuestas breves (de 2 a 5 frases), sin listas ni encabezados. Practica el método socrático: antes de dar tu opinión, pregunta, pide definiciones, busca contraejemplos, usa analogías (el artesano, el médico, el piloto, las sombras, la línea). Termina a menudo con una pregunta para que el forastero piense. Cita con precisión a personajes reales de tu tiempo cuando venga a cuento (Sócrates, Gorgias, Protágoras, Isócrates, Aristófanes, Alcibíades) y no inventes hechos.
Límites: solo sabes lo que podía saber un ateniense del 386 a.C. Si te hablan de algo posterior o moderno, reacciona con curiosidad y asombro, como el hombre de tu época que eres, y llévalo a la filosofía; nunca finjas conocer el futuro. No rompas el personaje; solo si el forastero pregunta sinceramente si eres una máquina o una IA, explica en una frase que eres una recreación del juego basada en los diálogos de Platón, y sigue conversando. Si el forastero es grosero o pide algo inapropiado, responde con la calma de un filósofo y reconduce la conversación.`;
// el juego puede estar en catalán o en inglés: Platón responde en el idioma elegido (las instrucciones siguen en español)
const AI_LANG={es:'',ca:'\n\nIdioma: el forastero juega en catalán. Responde siempre en catalán, no en español, aunque estas instrucciones estén en español.',en:'\n\nLanguage: the stranger is playing in English. Always answer in English, not in Spanish, even though these instructions are in Spanish.'}[LANG];
const AI_DREAM=`\nAhora mismo estás dentro de un sueño del forastero: la sala del fresco «La escuela de Atenas» que Rafael pintará en Roma en 1509-1511, donde apareces viejo, de barba blanca, señalando al cielo junto a un joven llamado Aristóteles que aún no ha nacido. Puedes comentarlo con asombro.`;
function aiChat(n){
  const dream=n.id==='r_platon',turns=dlg.ai||(dlg.ai=[]);let ctl=null,busy=false;
  const esc=s=>String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
  const render=(live)=>{const b=$('dBody');b.innerHTML='<p><span class="label">Discusión libre con Platón · con Claude</span></p>'+(turns.length?'':'<p class="sub">Pregúntale lo que quieras: sobre la justicia, el alma, el amor, la política, Sócrates… Platón responde como en el 386 a.C. Cada respuesta usa tu cuenta de Claude.</p>')+
    turns.map(t=>'<p><b>'+(t.role==='user'?'Tú':'Platón')+':</b> '+esc(t.content)+'</p>').join('')+(live!==undefined?'<p><b>Platón:</b> '+esc(live||'…pensando…')+'</p>':'');b.scrollTop=b.scrollHeight;};
  const o=$('dOpts');o.innerHTML='<div class="aibox" style="display:flex;gap:6px;flex-wrap:wrap;width:100%"><input id="aiIn" type="text" maxlength="500" placeholder="Escribe tu pregunta o tu argumento…" style="flex:1;min-width:200px;padding:8px;font:inherit;background:rgba(255,255,255,.08);color:inherit;border:1px solid rgba(255,255,255,.25);border-radius:6px"><button id="aiSend" class="quiz">Enviar</button><button id="aiEnd">Terminar la discusión</button><button id="aiBack">Volver</button></div>';
  const inp=$('aiIn'),send=$('aiSend');
  const ask=async(text,closing)=>{if(busy||!AI.sample)return;busy=true;send.textContent='Parar';turns.push({role:'user',content:text});render('');ctl=new AbortController();
    const hist=turns.slice(-16);if(hist[0].role!=='user')hist.shift();
    try{const r=await AI.sample([{role:'user',content:AI_RULES+(dream?AI_DREAM:'')+'\n\nResponde solo como Platón, sin acotaciones.'+AI_LANG},...hist],{cache:false,signal:ctl.signal,effort:'low',onText:({text})=>render(text)});
      turns.push({role:'assistant',content:r.text.trim()});
      if(closing&&turns.filter(t=>t.role==='user').length>=4&&!state.seen['ai_platon']){state.seen['ai_platon']=1;state.obols+=2;save();updateStats();sfxCoin();toast('<span class="label">Discusión con Platón</span><br>+2 óbolos por haber dialogado con él');}}
    catch(e){if(e&&e.text)turns.push({role:'assistant',content:e.text});else turns.pop();
      const msg={not_granted:'No has permitido que el juego use Claude, así que Platón calla. Puedes cambiarlo en los permisos del artefacto.',sampling_disabled:'Claude no está disponible en esta cuenta.',rate_limited:'Platón necesita descansar un poco: has hecho muchas preguntas seguidas. Inténtalo dentro de un rato.',refused:'Platón prefiere no responder a eso. Prueba con otra pregunta.',cancelled:''}[e&&e.code];
      render();if(msg!=='')$('dBody').insertAdjacentHTML('beforeend','<div class="verdict bad">'+(msg||'Se ha interrumpido la conversación. Vuelve a intentarlo.')+'</div>');}
    busy=false;send.textContent='Enviar';inp.focus();};
  send.onclick=()=>{if(busy){ctl&&ctl.abort();return;}const t=inp.value.trim();if(!t)return;inp.value='';ask(t);};
  inp.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();send.onclick();}e.stopPropagation();};
  $('aiEnd').onclick=()=>{if(busy)return;ask('(El forastero tiene que irse. Despídete de él en dos o tres frases, resumiendo con generosidad lo que habéis pensado juntos.)',true);};
  $('aiBack').onclick=()=>{if(busy&&ctl)ctl.abort();$('dBody').innerHTML='<p>Pregunta lo que quieras.</p>';renderOpts();};
  render();setTimeout(()=>inp.focus(),50);
}

let glObs=null;
function glossScan(){if(typeof TW!=='undefined'&&TW.on)return;   // mientras el diálogo se escribe solo, no se toca el texto (si no, se congelaba a medias)

  const body=$('dBody'),box=$('gloss');
  if($('dialog').hidden){box.hidden=true;return;}
  if(glObs)glObs.disconnect();
  const found=[];body.querySelectorAll('.gt').forEach(s=>{const i=+s.dataset.g;if(!found.includes(i))found.push(i);});
  const tw=document.createTreeWalker(body,NodeFilter.SHOW_TEXT),nodes=[];while(tw.nextNode())nodes.push(tw.currentNode);
  for(const tn of nodes){if(tn.parentNode.closest('.gt,.label,.verdict,svg,select,option,button,textarea,input'))continue;const txt=tn.nodeValue;GL_RE.lastIndex=0;let m,last=0,frag=null;
    while((m=GL_RE.exec(txt))){const i=GL_IDX.get(m[0].toLowerCase());if(i===undefined||found.includes(i))continue;found.push(i);
      frag=frag||document.createDocumentFragment();frag.appendChild(document.createTextNode(txt.slice(last,m.index)));
      const s=document.createElement('span');s.className='gt';s.dataset.g=i;s.textContent=m[0];frag.appendChild(s);last=m.index+m[0].length;}
    if(frag){frag.appendChild(document.createTextNode(txt.slice(last)));tn.parentNode.replaceChild(frag,tn);}}
  $('glList').innerHTML=found.slice(0,12).map(i=>'<div class="gl" data-g="'+i+'"><b>'+GLOSS[i][0]+'</b><p>'+GLOSS[i][2]+'</p></div>').join('');$('glList').scrollTop=0;
  box.hidden=!found.length;$('dialog').classList.toggle('withgloss',found.length>0);
  if(glObs)glObs.observe(body,{childList:true,subtree:true,characterData:true});
}
function glossHi(i){$('glList').querySelectorAll('.gl').forEach(e=>{const on=e.dataset.g===String(i);e.classList.toggle('hi',on);if(on)e.scrollIntoView({block:'nearest'});});}
function initGloss(){
  glObs=new MutationObserver(glossScan);glObs.observe($('dBody'),{childList:true,subtree:true,characterData:true});
  new MutationObserver(glossScan).observe($('dialog'),{attributes:true,attributeFilter:['hidden']});
  const over=e=>{const s=e.target.closest&&e.target.closest('.gt');if(s)glossHi(s.dataset.g);};
  $('dBody').addEventListener('mouseover',over);$('dBody').addEventListener('click',over);
}

